using UnityEngine;
namespace LWS.TruckBuzkashi {public sealed class BuzImpact:MonoBehaviour {public BuzMatch match;public int slot;public float LastBarrierContact{get;private set;}=float.NegativeInfinity;public void Clear(){LastBarrierContact=float.NegativeInfinity;}void OnCollisionEnter(Collision collision){var other=collision.collider.GetComponentInParent<BuzImpact>();if(other!=null&&other.slot!=slot)match.Contact(slot,other.slot,collision);}void OnCollisionStay(Collision collision){if(collision.collider.isTrigger||collision.collider.GetComponentInParent<BuzSolidBarrier>()==null)return;for(int i=0;i<collision.contactCount;i++)if(Mathf.Abs(collision.GetContact(i).normal.y)<.6f){LastBarrierContact=Time.time;break;}}}}
